static unsigned g_guest_futex_log_count;

/* H20: single waiter slot (no multi-waiter queue). */
static long g_futex_waiter_uaddr;
static int g_futex_waiter_val;
static int g_futex_waiter_parked;
static int g_futex_waiter_side;

/*
 * Linux 202: futex — single-threaded / single-waiter guest (H20).
 * - timeout_ptr set: poll until deadline (sti+hlt), return -ETIMEDOUT (-110)
 *   WITHOUT clearing *uaddr (word stays locked — correct for timed wait).
 * - untimed WAIT: if *uaddr!=val → 0; else record one parked waiter, then clear
 *   *uaddr and return 0 (Qt single-thread workaround — must not hang smoke).
 * - WAKE: clear parked slot if matching uaddr; return 1 (woke) or 0.
 */
long sys_futex(long uaddr, long op, long val, long timeout_ptr, long uaddr2, long val3)
{
    int cmd = (int)(op & 0x7f);
    int *word;

    (void)uaddr2;
    (void)val3;

    switch (cmd) {
    case 0: /* FUTEX_WAIT */
    case 9: /* FUTEX_WAIT_BITSET */
        if (uaddr == 0 || !bfree_user_vaddr_mapped((uint64_t)(uintptr_t)uaddr)) {
            return -14; /* EFAULT */
        }
        word = (int *)(uintptr_t)uaddr;
        if (timeout_ptr != 0) {
            struct timespec *ts = (struct timespec *)(uintptr_t)timeout_ptr;
            uint64_t wait_us;
            uint64_t start;

            if (!bfree_user_vaddr_mapped((uint64_t)(uintptr_t)ts)) {
                return -14;
            }
            wait_us = bfree_timespec_to_us(ts);
            start = knl_get_current_time();
            /* Allow timer IRQ so knl_get_current_time advances (SYSCALL clears IF). */
            __asm__ volatile("sti" ::: "memory");
            while ((knl_get_current_time() - start) < wait_us) {
                if (*(volatile int *)word != (int)val) {
                    __asm__ volatile("cli" ::: "memory");
                    if (g_guest_futex_log_count < 8U) {
                        ++g_guest_futex_log_count;
                        uart_puts("[FUTEX] wait woken\n");
                    }
                    return 0;
                }
                __asm__ volatile("hlt" ::: "memory");
            }
            __asm__ volatile("cli" ::: "memory");
            /* Timed out: leave *uaddr unchanged (must not clear). */
            if (g_guest_futex_log_count < 8U) {
                ++g_guest_futex_log_count;
                uart_puts("[FUTEX] wait ETIMEDOUT\n");
            }
            return -110; /* ETIMEDOUT */
        }
        /*
         * Untimed WAIT: equality check, then single-slot park + clear for Qt.
         * Real block would hang phase3_pty_smoke / single-thread guests.
         */
        if (*(volatile int *)word != (int)val) {
            return 0;
        }
        g_futex_waiter_uaddr = uaddr;
        g_futex_waiter_val = (int)val;
        g_futex_waiter_parked = 1;
        g_futex_waiter_side = g_coop_side;
        *word = 0;
        if (g_guest_futex_log_count < 8U) {
            ++g_guest_futex_log_count;
            uart_puts("[FUTEX] wait\n");
        }
        return 0;
    case 1: /* FUTEX_WAKE */
    case 10: /* FUTEX_WAKE_BITSET */
        if (g_futex_waiter_parked &&
            (uaddr == 0 || uaddr == g_futex_waiter_uaddr)) {
            g_futex_waiter_parked = 0;
            g_futex_waiter_uaddr = 0;
            return 1;
        }
        return (val > 0) ? 1 : 0;
    case 3: /* FUTEX_REQUEUE */
    case 4: /* FUTEX_CMP_REQUEUE */
    case 5: /* FUTEX_WAKE_OP */
        return 0;
    default:
        return -22; /* EINVAL */
    }
}
